"""Ephemeral personal prompt and AI Context website demonstrations."""
from html import escape
from flagship_shared import text, href, icon

def context_cards(lang, uid):
    t = lambda z,e: text(lang,z,e)
    cards = [
        ('info', 'person', '我的信息', 'My Information', '希望 AI 知道的背景', 'The background you choose to share'),
        ('rules', 'rules', '我的规则', 'My Rules', '希望 AI 如何回应', 'How you want AI to respond'),
        ('now', 'now', '我的现在', 'My Now', '眼下正在做的事', 'What you are working on now'),
        ('inputs', 'thought', '我的输入', 'My Inputs', '你愿意开放的个人主题', 'Personal topics you choose to open'),
    ]
    return f'''<div class="context-demo" data-context data-persona="{'writing' if uid=='home-context' else 'product'}">
      <div class="context-control"><div><strong>{t('由你决定，开放多少。','Choose how much to share.')}</strong><span>{t('演示状态 · 没有连接真实 AI','Demo state · No live AI connection')}</span></div>
      <button class="switch" type="button" role="switch" aria-checked="false" data-context-global aria-label="{t('允许 AI 读取','Allow AI access')}"><span></span></button></div>
      <div class="context-grid">{''.join(f'''<article class="context-card" data-card="{key}"><button type="button" class="context-card-open" data-context-open="{key}" aria-label="{t('查看','View')} {t(zh,en)}">{icon(ic)}<h3>{t(zh,en)}</h3><p>{t(dz,de)}</p></button><div class="context-card-bottom"><span data-card-status>{t('未开放','Closed')}</span><button type="button" class="switch small-switch" role="switch" aria-checked="false" data-context-scope="{key}" aria-label="{t('开放','Open')} {t(zh,en)}"><span></span></button></div></article>''' for key,ic,zh,en,dz,de in cards)}</div>
      <p class="context-summary" data-context-status role="status">{t('总访问已关闭。卡片与主题分别选择。','Main access is off. Cards and topics are chosen separately.')}</p>
      <dialog class="context-dialog personal-dialog" id="{uid}-context-dialog" data-context-dialog aria-labelledby="{uid}-context-title" aria-describedby="{uid}-context-note"><div class="dialog-heading"><h3 id="{uid}-context-title" data-context-title></h3><button class="icon-button" type="button" data-context-close aria-label="{t('关闭详情','Close details')}">{icon('close')}</button></div><div data-context-detail></div><p class="personal-feedback" data-context-edit-status role="status" aria-live="polite"></p><p class="fine" id="{uid}-context-note">{t('虚构示例，刷新即重置。打开或修改内容不会改变读取权限。','Fictional example; resets on reload. Opening or editing content does not change access.')}</p></dialog>
    </div>'''

def prompts(lang, uid='prompt'):
    t=lambda z,e:text(lang,z,e)
    is_home = uid == 'home-prompt'
    choices=[('结合我的实际限制，重新考虑这个问题。','Reconsider this using my actual constraints.'),('给我一个不同的角度。','Give me a different perspective.'),('先检查我的前提是否成立。','Check my assumptions first.'),('保留不确定性，不要急着给结论。','Keep the uncertainty. Do not rush to a conclusion.'),('用一个具体的例子说明。','Explain it with a concrete example.'),('把重点说得更清楚一些。','Make the main point clearer.')]
    return f'''<div class="prompt-demo" data-prompt-demo><div class="composer-heading"><span>{t('回到下一次对话','The next conversation') if is_home else t('接着往下想','Continue the thought')}</span><span>{t('本页输入框','Sample composer')}</span></div><div class="composer-space"><p>{t('关于那篇还没写完的随笔，<br>我还想再想一想。','That unfinished piece.<br>I want to think about it again.') if is_home else t('“我已经说清楚过一次。<br>这次，不必从头再来。”','“I found the words once.<br>I do not need to start over.”')}</p></div><div class="prompt-anchor"><div class="prompt-board" id="{uid}-board" data-prompt-board hidden><div class="prompt-list" data-prompt-list>{''.join(f'<button type="button" data-prompt-id="p{i}" data-prompt-pick="{escape(t(z,e),quote=True)}">{escape(t(z,e))}</button>' for i,(z,e) in enumerate(choices))}</div><div class="prompt-toolbar"><label>{icon('search')}<input type="search" data-prompt-search placeholder="{t('找一句自己的话','Find your own words')}" aria-label="{t('搜索示例提示词','Search sample prompts')}"></label><button class="prompt-manage-button" type="button" data-prompt-manage aria-haspopup="dialog" aria-controls="{uid}-prompt-manager" aria-label="{t('管理个人提示词','Manage personal prompts')}">{icon('edit')}</button></div><p class="prompt-empty" data-prompt-empty hidden>{t('没有找到，换个词试试。','No match. Try a different word.')}</p></div><button type="button" class="prompt-capsule" data-prompt-id="p0" data-prompt-pick="{escape(t(*choices[0]),quote=True)}">{t('结合我的实际限制…','Use my actual constraints…')}</button><button type="button" class="prompt-toggle" data-prompt-toggle aria-expanded="false" aria-controls="{uid}-board" aria-label="{t('打开个人提示词','Open personal prompts')}"><span class="double-card" aria-hidden="true"></span></button></div><label class="sr-only" for="{uid}-composer">{t('示例输入框','Sample composer')}</label><textarea id="{uid}-composer" data-composer rows="3" placeholder="{t('先写一点，再选择一句提示词…','Start a draft, then choose a prompt…')}">{t('我想从搬家那天的一个细节写起。','I want to start with one detail from moving day.') if is_home else t('我目前更在意使用体验。','Right now, I care more about the experience.')}</textarea><div class="composer-footer"><span data-prompt-status role="status">{t('只填入，不自动发送。','Fills the composer. Never sends.')}</span><button class="quiet-button" data-prompt-reset type="button">{t('重置示例','Reset sample')}</button></div><dialog class="prompt-manager personal-dialog" id="{uid}-prompt-manager" data-prompt-manager aria-labelledby="{uid}-prompt-manager-title" aria-describedby="{uid}-prompt-manager-note"><div class="dialog-heading"><h3 id="{uid}-prompt-manager-title">{t('自己的常用表达','Your useful phrases')}</h3><button class="icon-button" type="button" data-prompt-manager-close aria-label="{t('关闭提示词管理','Close prompt management')}">{icon('close')}</button></div><p class="fine personal-dialog-intro" id="{uid}-prompt-manager-note">{t('编辑、固定或调整顺序。更改只留在本页，刷新即重置。','Edit, pin or change the order. Changes stay in this page and reset on reload.')}</p><div class="prompt-manager-list" data-prompt-manager-list></div><div class="prompt-manager-footer"><p class="personal-feedback" data-prompt-manager-status role="status" aria-live="polite"></p><button class="quiet-button" type="button" data-prompt-undo hidden>{t('撤销隐藏','Undo hide')}</button></div></dialog></div>'''
